In "build": `"electronLanguages": ["fr", "en-US"],`. Confidence that electron-builder 24.13.3 honours this key on Windows is moderate (it began as a macOS-only option); electron-builder validates its config, so if the key is rejected the release build fails loudly. Then use an afterPack hook instead ("afterPack": "./afterPack.js"; not packaged since `files` is explicit):
const fs = require('fs'), path = require('path');
exports.default = async ({ appOutDir, electronPlatformName }) => {
  if (electronPlatformName !== 'win32') return;
  const dir = path.join(appOutDir, 'locales');
  for (const f of fs.readdirSync(dir))
    if (f !== 'fr.pak' && f !== 'en-US.pak') fs.rmSync(path.join(dir, f));
};
